void mainImage(out vec4 fragColor, in vec2 uv, in float time) {
    vec2 p = uv * 2.0 - 1.0;
    float r = length(p);
    float a = atan(p.y, p.x);

    // Swirling vortex SDF
    float spiral = sin(a * 4.0 - time * 6.28318 + r * 6.0);
    float orb = r - 0.72 + 0.08 * spiral;

    if (orb > 0.06) {
        fragColor = vec4(0.0);
        return;
    }

    float core = max(0.0, 1.0 - r / 0.75);
    float ring = max(0.0, 1.0 - abs(orb) / 0.12);
    float intensity = clamp(core * 0.7 + ring * 0.9 + 0.25 * spiral, 0.0, 1.0);

    vec3 col = vec3(sin(intensity * 3.14159) * 0.6, intensity * 0.9, 0.5 + intensity * 0.5);
    fragColor = vec4(col, 1.0);
}
